    "meaning": {
      "prompt": "昨日はとなりの村から歩いて帰ってきた。\n\n歩いて",
      "options": [
        "ないて",
        "はいて",
        "あるいて",
        "つづいて"
      ],
      "answerIndex": 2
    },
    "optionExplanations": [
      "「ないて」是「泣いて」（哭）的讀音，跟「歩いて」不同，錯誤。",
      "「はいて」是「履いて」（穿鞋襪）的讀音，跟「歩いて」不同，錯誤。",
      "「あるいて」是「歩いて」正確的讀音，為正解。",
      "「つづいて」是「続いて」（繼續、接著）的讀音，跟「歩いて」不同，錯誤。"
    ]
